from flask import Flask, jsonify

app = Flask(__name__)


@app.post("/checkout")
def checkout():
    user = get_current_user()

    op.identify(str(user.id), {
        "email": user.email,
        "firstName": user.first_name,
    })

    op.track("checkout_started", {"cart_value": 49.0})
    op.increment(str(user.id), "checkout_count", 1)

    return jsonify(ok=True)
